def datos_existentes(apps, schema_editor):
    """Rellena lo nuevo a partir de lo que ya había, sin cambiar ningún importe."""
    Asiento = apps.get_model("cuadro_cuentas", "Asiento")
    Apunte = apps.get_model("cuadro_cuentas", "Apunte")
    Ejercicio = apps.get_model("cuadro_cuentas", "Ejercicio")
    DatosEmpresa = apps.get_model("cuadro_cuentas", "DatosEmpresa")

    empresa = DatosEmpresa.objects.order_by("id").first()
    if empresa:
        Ejercicio.objects.filter(empresa__isnull=True).update(empresa=empresa)

    # El nº de factura que se guardaba como documento pasa a ser el «Número» del asiento
    for asiento in Asiento.objects.exclude(referencia_origen="").filter(numero_externo=""):
        asiento.numero_externo = asiento.referencia_origen[:60]
        asiento.save(update_fields=["numero_externo"])
    for asiento in Asiento.objects.filter(estado="contabilizado", contabilizado_en__isnull=True):
        asiento.contabilizado_en = asiento.creado
        asiento.save(update_fields=["contabilizado_en"])

    # Nº de apunte 1, 2, 3... dentro de cada asiento: primero el Debe y luego el Haber
    for asiento in Asiento.objects.all():
        apuntes = sorted(Apunte.objects.filter(asiento=asiento), key=lambda a: (a.haber > 0, a.orden, a.id))
        for i, a in enumerate(apuntes, 1):
            if a.orden != i:
                a.orden = i
                a.save(update_fields=["orden"])


